export function openSourcePage(intro) {
  return intro('EMBASSY COMMONS', 'Open source.<br>Independent by design.', 'A volunteer initiative to help people build independent Bitcoin communities. We share software, knowledge and experience so local teams can move themselves and Bitcoin forward.') + `
  <section class="page-body"><div class="proposal-grid"><div>
    <section class="proposal-section"><h2>Build locally. Share what works.</h2><p>Every country has its own people, culture and needs. Your team owns and runs its own initiative: website, repository, hosting, data, programme and decisions. There is no required DBE account, subscription, central approval or ongoing DBE service.</p><div class="package-list"><div><b>Reusable software</b><small>Complete source code that your team can fork, change, run and maintain on its own infrastructure.</small></div><div><b>Practical knowledge</b><small>Openly licensed community formats and playbooks to adapt, translate and improve with attribution.</small></div><div><b>Selected public data</b><small>Reviewed records with clear sources and rights. Private member data stays private.</small></div><div><b>Local ownership</b><small>Your initiative belongs to your team. No required affiliation, exclusivity or obligation to contribute back.</small></div></div></section>
    <section class="proposal-section"><h2>A conversation when it helps.</h2><p>You can use the open-source toolkit without asking our permission. If you would like voluntary guidance, tell us who is involved and what you want to create. We can discuss a first step together; support depends on volunteer availability.</p><div class="roadmap"><div class="roadmap-item"><b>01 / INTRO</b><div><h3>Introduce your team.</h3><p>A short introduction about your community, plans and people.</p></div></div><div class="roadmap-item"><b>02 / MEET</b><div><h3>Have a conversation.</h3><p>Discuss local needs, responsibilities and a realistic first step.</p></div></div><div class="roadmap-item"><b>03 / BUILD</b><div><h3>Choose your own next step.</h3><p>Start independently or agree on optional collaboration. Any use of the DBE brand is a separate arrangement.</p></div></div></div><div class="hero-actions"><a class="button ink" href="#apply">Request an introduction <span>↗</span></a><a class="button outline" href="https://github.com/Vinnybtc/embassy-commons" target="_blank" rel="noopener">Get the source code <span>↗</span></a></div></section>
    <section class="proposal-section"><h2>Clear rights. Clear expectations.</h2><p>The code uses MIT; original knowledge uses CC BY 4.0 and generic demo data uses CC0. These licences grant reuse rights, without requiring membership or support. Fonts have their own open licences. DBE names, logos, photography and third-party material have separate rights. These do not make your local initiative dependent on us: use your own identity. Private member data is never part of the shared toolkit.</p><div class="doc-links"><a href="https://opensource.org/osd" target="_blank" rel="noopener">What open source means <span>↗</span></a><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">Creative Commons Attribution 4.0 <span>↗</span></a></div></section>
  </div><aside><div class="preview"><div class="eyebrow">VOLUNTARILY SHARED</div><h3>Help people.<br>Help Bitcoin.</h3><p>We share this work voluntarily. The goal is to help people learn, build local communities and bring Bitcoin further. Your initiative remains yours.</p><div class="preview-bottom"><span>LOCAL AUTONOMY</span><span>SHARED KNOWLEDGE</span></div></div></aside></div></section>`;
}

export function homeIntroductionSection() {
  return `<section class="section commons-introduction"><div class="section-heading"><div><div class="eyebrow">EMBASSY COMMONS</div><h2>Open source.<br>Independent by design.</h2><p>A volunteer-built foundation to help people and Bitcoin. Your team runs everything itself. Use the toolkit independently, or request an introduction if guidance would help.</p></div><a class="text-link" href="#opensource">How Embassy Commons works <span>↗</span></a></div><div class="hero-actions"><a class="button ink" href="#apply">Request an introduction <span>↗</span></a><span class="micro">VOLUNTARILY SHARED · OPTIONAL INTRODUCTION</span></div></section>`;
}

export function applicationPage(intro, esc, draft, prepared) {
  const textField = (key, label, options = '') => `<div class="field"><label for="intro-${key}">${label}</label><input id="intro-${key}" name="${key}" value="${esc(draft[key] ?? '')}" ${options}></div>`;
  return intro('A FIRST CONVERSATION', 'Introduce your community.', 'Tell us about your people, your plans and where you want to build. A short introduction is enough to begin.') + `
  <section class="page-body"><div class="wizard-layout"><div class="wizard"><h2>Request an introduction.</h2><p class="description">We will prepare an email to Dutch Bitcoin Embassy. You review it and send it from your own email app. Nothing is sent automatically.</p>
    <form id="introduction-form"><div class="form-grid">
      ${textField('fullName', 'Your name', 'required minlength="2" maxlength="100" autocomplete="name"')}
      ${textField('email', 'Email address', 'type="email" required maxlength="254" autocomplete="email"')}
      ${textField('country', 'Country', 'required minlength="2" maxlength="80" autocomplete="country-name"')}
      ${textField('city', 'City or region', 'required minlength="2" maxlength="100" autocomplete="address-level2"')}
      <div class="field full"><label for="intro-team">Who is on your team?</label><textarea id="intro-team" name="team" required minlength="2" maxlength="300">${esc(draft.team ?? '')}</textarea><small>Describe your team and experience. A solo founder is welcome too.</small></div>
      <div class="field full"><label for="intro-plans">What would you like to build?</label><textarea id="intro-plans" name="plans" required minlength="20" maxlength="1000">${esc(draft.plans ?? '')}</textarea></div>
      <div class="field full"><label for="intro-website">Website or community link <span class="micro">OPTIONAL</span></label><input id="intro-website" name="website" type="url" maxlength="300" placeholder="https://" value="${esc(draft.website ?? '')}"></div>
    </div><div id="introduction-errors" class="errors" role="alert"></div><div class="wizard-actions"><span class="micro">REVIEW BEFORE SENDING</span><button class="button ink" type="submit">Prepare introduction <span>→</span></button></div></form>
    ${prepared ? `<section class="introduction-result" aria-live="polite"><h2>Your introduction is ready.</h2><p class="description">Addressed to <a href="mailto:info@dutchbitcoinembassy.com">info@dutchbitcoinembassy.com</a>. It has not been sent. Review the text, then open your email app or copy the message.</p><pre class="code-block">${esc(prepared.body)}</pre><div class="hero-actions"><a class="button ink" id="introduction-email" href="${esc(prepared.mailto)}">Open email app <span>↗</span></a><button class="button outline" type="button" data-action="copy-introduction">Copy message</button></div><p class="source-note">If your email app does not open, send the message to info@dutchbitcoinembassy.com with the subject “${esc(prepared.subject)}”.</p></section>` : ''}
  </div><aside><div class="preview"><div class="eyebrow">WHAT HAPPENS NEXT</div><h3>A conversation.<br>Then a plan.</h3><p>We volunteer our time to help people and Bitcoin. If we can help, we discuss your needs and possible next steps. An introduction is optional; you can always start independently.</p><div class="preview-bottom"><span>VOLUNTARY HELP</span><span>NO REQUIRED AFFILIATION</span></div></div><p class="preview-caption">Your details stay in this page until you choose to open your email app or copy the message.</p><p class="source-note">For a direct introduction, email <a href="mailto:info@dutchbitcoinembassy.com">info@dutchbitcoinembassy.com</a>. Please keep private member lists, financial records and wallet details out of your introduction.</p></aside></div></section>`;
}
